import type { AgentInfo, EngineInterface, Register, SessionRateLimit } from 'claude-code'

// Lo que dibuja el HUD bajo el prompt; se recalcula con los timers y con cada evento
type Git = { branch: string; dirty: number; ahead: number; behind: number }
type Bg = { id: string; type: string; label: string }

let model = ''
let project = ''
let git: Git | null = null
let ctxPercent: number | undefined
let ctxTokens: number | undefined
let ctxWindow = 0
let limits: SessionRateLimit[] = []
let tool = ''
// Herramientas usadas desde el último prompt, en orden de primera aparición
let tally = new Map<string, number>()
// Subagentes en curso, y cuándo se vio cada uno por primera vez
let running: AgentInfo[] = []
const firstSeen = new Map<string, number>()
// Tareas de fondo que no son subagentes (shells, monitores, workflows)
let background: Bg[] = []

// Paleta de tu terminal (Base16 Default Dark), la misma que pinta claude-hud
// con sus códigos ANSI; los mods solo aceptan hex, así que va explícita
const C = {
  model: '#75b5aa',
  project: '#f4bf75',
  git: '#aa759f',
  branch: '#75b5aa',
  context: '#90a959',
  usage: '#82b8c8',
  warning: '#f4bf75',
  usageWarning: '#aa759f',
  critical: '#ac4142',
  ok: '#90a959',
  label: '#8e8e8e',
}

const UMBRALES = [80, 90, 95]
const RAMAS_PROD = ['main', 'master']

// --- helpers puros -------------------------------------------------------

function modelLabel(id: string): string {
  const m = /(opus|sonnet|haiku|fable)-(\d+)-(\d+)/i.exec(id)
  const [, fam = '', major = '', minor = ''] = m ?? []
  if (!m) return id
  return fam.charAt(0).toUpperCase() + fam.slice(1).toLowerCase() + ' ' + major + '.' + minor
}

function barParts(percent: number, width = 10): [string, string] {
  const filled = Math.max(0, Math.min(width, Math.round((percent / 100) * width)))
  return ['█'.repeat(filled), '░'.repeat(width - filled)]
}

function contextColor(percent: number): string {
  if (percent >= 85) return C.critical
  if (percent >= 70) return C.warning
  return C.context
}

function usageColor(percent: number): string {
  if (percent >= 90) return C.critical
  if (percent >= 75) return C.usageWarning
  return C.usage
}

function kTokens(n: number): string {
  return n >= 1000 ? Math.round(n / 1000) + 'k' : String(n)
}

function duration(ms: number): string {
  const mins = Math.max(0, Math.round(ms / 60000))
  if (mins >= 1440) return Math.floor(mins / 1440) + 'd ' + Math.floor((mins % 1440) / 60) + 'h'
  if (mins >= 60) return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm'
  if (mins >= 1) return mins + 'm'
  return Math.max(0, Math.round(ms / 1000)) + 's'
}

function untilReset(resetsAt: string | undefined, now: number): string {
  return resetsAt ? duration(Date.parse(resetsAt) - now) : ''
}

function limitLabel(kind: string): string {
  if (kind === 'five_hour') return '5h'
  if (kind === 'seven_day') return '7d'
  return kind
}

function clip(text: string, max: number): string {
  const flat = text.replace(/\s+/g, ' ').trim()
  return flat.length > max ? flat.slice(0, max - 1) + '…' : flat
}

export function parseGit(porcelain: string): Git | null {
  const lines = porcelain.split('\n').filter(l => l.length > 0)
  const head = lines[0]
  if (!head || !head.startsWith('## ')) return null
  const info = head.slice(3)
  const branch = (info.split('...')[0] ?? '').replace(/^No commits yet on /, '').split(' ')[0] ?? ''
  const ahead = Number(/ahead (\d+)/.exec(info)?.[1] ?? 0)
  const behind = Number(/behind (\d+)/.exec(info)?.[1] ?? 0)
  return { branch, dirty: lines.length - 1, ahead, behind }
}

function toolName(name: string): string {
  return name.startsWith('mcp__') ? name.split('__').pop() ?? name : name
}

function shortTool(e: { tool: string } & Record<string, unknown>): string {
  const target = (e.file_path ?? e.pattern ?? e.command ?? e.description ?? '') as string
  const base = String(target).split('/').pop() ?? ''
  const shown = clip(base, 40)
  return shown ? toolName(e.tool) + ': ' + shown : toolName(e.tool)
}

// --- lecturas (reciben $) -----------------------------------------------

async function refreshGit($: EngineInterface) {
  try {
    const r = await $.process.run(['git', 'status', '--porcelain=v1', '-b'], { timeoutMs: 5000 })
    git = r.exitCode === 0 ? parseGit(r.stdout) : null
  } catch {
    git = null
  }
}

async function refreshUsage($: EngineInterface) {
  const u = await $.session.usage()
  ctxPercent = u.context.percent
  ctxTokens = u.context.tokens
  ctxWindow = u.context.window
  limits = u.rateLimits
}

async function refreshAgents($: EngineInterface) {
  const now = await $.clock.now()
  const all = await $.agent.list()
  const before = running.length
  running = all.filter(a => a.status === 'running')
  for (const a of running) if (!firstSeen.has(a.id)) firstSeen.set(a.id, now)
  if (running.length > 0 || before > 0) $.ui.invalidate('ui.render')
}

async function refreshAll($: EngineInterface) {
  model = modelLabel(await $.session.model())
  project = (await $.session.cwd()).split('/').pop() ?? ''
  await refreshGit($)
  await refreshUsage($)
  await refreshAgents($)
  $.ui.invalidate('ui.render')
}

// Avisa una sola vez por umbral y por ventana (la clave incluye el reset)
async function warnLimits($: EngineInterface, rateLimits: SessionRateLimit[]) {
  for (const l of rateLimits) {
    const crossed = UMBRALES.filter(u => l.percentUsed >= u).pop()
    if (crossed === undefined) continue
    const key = 'aviso:' + l.kind + ':' + (l.resetsAt ?? '')
    const last = Number((await $.store.get(key)) ?? 0)
    if (crossed <= last) continue
    await $.store.set(key, crossed)
    const reset = untilReset(l.resetsAt, await $.clock.now())
    $.ui.toast('Uso ' + limitLabel(l.kind) + ' al ' + Math.round(l.percentUsed) + '%' + (reset ? ' · reinicia en ' + reset : ''), { timeoutMs: 8000 })
  }
}

// --- hooks ---------------------------------------------------------------

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await refreshAll($)
    $.clock.every(15000, () => void refreshAll($))
    // Los subagentes cambian rápido y el contador de tiempo avanza solo
    $.clock.every(3000, () => void refreshAgents($))
    return started
  })

  on('turn.start', async ($, e, next) => {
    model = modelLabel(await $.session.model())
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    tally = new Map()
    $.ui.invalidate('ui.render')
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    ctxPercent = e.context.percent
    ctxTokens = e.context.tokens
    ctxWindow = e.context.window
    limits = e.rateLimits
    if (e.changed.includes('rateLimits')) await warnLimits($, e.rateLimits)
    $.ui.invalidate('ui.render')
    return next(e)
  })

  // Herramienta en curso del hilo principal; las de los subagentes no se cuentan
  on('tool.call', async ($, e, next) => {
    if (e.agentId) return next(e)
    tool = shortTool(e as { tool: string } & Record<string, unknown>)
    tally.set(toolName(e.tool), (tally.get(toolName(e.tool)) ?? 0) + 1)
    $.ui.invalidate('ui.render')
    try {
      return await next(e)
    } finally {
      tool = ''
      if (e.tool === 'Bash' || e.tool === 'Edit' || e.tool === 'Write') await refreshGit($)
      if (e.tool === 'Agent') await refreshAgents($)
      $.ui.invalidate('ui.render')
    }
  })

  // Al cerrar cada turno Claude Code informa el trabajo de fondo vivo: es la
  // fuente de los shells y monitores, que $.agent.list() no lista
  on('classic.Stop', async ($, e, next) => {
    background = (e.background_tasks ?? [])
      .filter(t => t.type !== 'subagent')
      .map(t => ({ id: t.id, type: t.type, label: clip(t.command ?? t.name ?? t.description, 50) }))
    $.ui.invalidate('ui.render')
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    tool = ''
    await refreshGit($)
    $.ui.invalidate('ui.render')
    return next(e)
  })

  // Bajo el prompt, como el statusLine de claude-hud; la línea de Claude Code
  // (modo, agentes, PR) se conserva debajo
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const theirs = await next(e)
    if (!model) return theirs
    const { Box, Text } = $.ui.resolve(e)
    const now = await $.clock.now()
    const sep = <Text> │ </Text>
    const bar = (percent: number, color: string, width = 10) => {
      const [full, empty] = barParts(percent, width)
      return (
        <Text>
          <Text color={color}>{full}</Text>
          <Text color={color} dimColor>{empty}</Text>
        </Text>
      )
    }

    // Línea 1: modelo · proyecto · git
    const onProd = git !== null && RAMAS_PROD.includes(git.branch)
    const gitSeg = git && (
      <Text>
        <Text color={C.git}>git:(</Text>
        <Text color={onProd ? C.critical : C.branch} bold={onProd}>{git.branch}{git.dirty > 0 ? '*' : ''}</Text>
        <Text color={C.git}>)</Text>
        {git.ahead > 0 ? <Text color={git.ahead >= 5 ? C.warning : C.branch}>{' ↑' + git.ahead}</Text> : ''}
        {git.behind > 0 ? <Text color={C.warning}>{' ↓' + git.behind}</Text> : ''}
        {git.dirty > 0 ? <Text color={C.label}>{' ' + git.dirty + (git.dirty === 1 ? ' cambio' : ' cambios')}</Text> : ''}
        {onProd ? <Text color={C.critical} bold>{'  ⚠ un push despliega a producción'}</Text> : ''}
      </Text>
    )
    const line1 = (
      <Box key="l1">
        <Text color={C.model}>[{model}]</Text>
        {sep}
        <Text color={C.project}>{project + ' '}</Text>
        {gitSeg ?? <Text color={C.label}>sin git</Text>}
      </Box>
    )

    // Línea 2: contexto y ventanas de uso
    const pct = ctxPercent ?? 0
    const ctxColor = contextColor(pct)
    const line2 = (
      <Box key="l2">
        <Text color={C.label}>Contexto </Text>
        {bar(pct, ctxColor)}
        <Text color={ctxColor}>{' ' + pct + '%'}</Text>
        <Text color={C.label}>{ctxTokens !== undefined ? ' ' + kTokens(ctxTokens) + '/' + kTokens(ctxWindow) : ''}</Text>
        {pct >= 80 ? <Text color={ctxColor}>{' · /compact'}</Text> : ''}
        {limits.map(l => (
          <Text key={l.kind}>
            {sep}
            <Text color={C.label}>{'Uso ' + limitLabel(l.kind) + ' '}</Text>
            {bar(l.percentUsed, usageColor(l.percentUsed))}
            <Text color={usageColor(l.percentUsed)}>{' ' + Math.round(l.percentUsed) + '%'}</Text>
            {l.resetsAt ? ' (reinicia en ' + untilReset(l.resetsAt, now) + ')' : ''}
          </Text>
        ))}
      </Box>
    )

    // Herramientas del turno, como claude-hud: ◐ Edit: x.py | ✓ Bash ×19
    const tools = [...tally.entries()].slice(-6)
    const toolsLine = (tools.length > 0 || (e.props.isWorking && tool)) && (
      <Box key="tools">
        {e.props.isWorking && tool ? <Text><Text color={C.warning}>◐</Text>{' ' + tool + (tools.length ? ' | ' : '')}</Text> : ''}
        {tools.map(([name, n], i) => (
          <Text key={'t-' + name}>
            {i > 0 ? ' | ' : ''}
            <Text color={C.ok}>✓</Text>
            {' ' + name}
            <Text color={C.label}>{' ×' + n}</Text>
          </Text>
        ))}
      </Box>
    )

    // Una línea por subagente y por tarea de fondo, como claude-hud
    const agentLines = running.slice(0, 4).map(a => (
      <Box key={'a-' + a.id}>
        <Text color={C.warning}>◐ </Text>
        <Text color={C.model}>{a.type}</Text>
        <Text>{': ' + clip(a.description, 50)}</Text>
        <Text color={C.label}>{' (' + duration(now - (firstSeen.get(a.id) ?? now)) + ')'}</Text>
      </Box>
    ))
    if (running.length > 4) agentLines.push(<Text key="a-more" color={C.label}>{'  +' + (running.length - 4) + ' agentes más'}</Text>)
    const bgLines = background.slice(0, 3).map(t => (
      <Box key={'b-' + t.id}>
        <Text color={C.usage}>▶ </Text>
        <Text color={C.model}>{t.type}</Text>
        <Text>{': ' + t.label}</Text>
      </Box>
    ))
    if (background.length > 3) bgLines.push(<Text key="b-more" color={C.label}>{'  +' + (background.length - 3) + ' tareas más'}</Text>)

    return (
      <Box flexDirection="column">
        {line1}
        {line2}
        {toolsLine || ''}
        {agentLines}
        {bgLines}
        {theirs}
      </Box>
    )
  })
}

